%% Lookup by slug atom or by binary name (case-insensitive).
pattern(Key) when is_atom(Key) ->
    lookup_by_slug(Key, patterns());
pattern(Key) when is_binary(Key) ->
    Lower = string:lowercase(Key),
    lookup_by_name(Lower, patterns()).

lookup_by_slug(_, []) -> not_found;
lookup_by_slug(K, [P = #{slug := K} | _]) -> {ok, P};
lookup_by_slug(K, [_ | Rest]) -> lookup_by_slug(K, Rest).

lookup_by_name(_, []) -> not_found;
lookup_by_name(K, [P = #{name := N} | Rest]) ->
    case string:lowercase(N) =:= K of
        true  -> {ok, P};
        false -> lookup_by_name(K, Rest)
    end.

names() ->
    [maps:get(name, P) || P <- patterns()].
